// Простое правило маршрутизации, без AI-классификации.
// Зеркало app/services/routing.py — при изменении правил правьте оба места.
const lead = $json.body ?? $json;

const source = (lead.source || 'telegram_bot').trim();
const comment = (lead.comment || '').trim();
const keywords = ['срочно', 'asap', 'сегодня', 'завтра', 'консультация'];

let route, priority, reason, tags;

if (source && source !== 'telegram_bot') {
  // Лид пришёл не из основной анкеты → отдельный контур поддержки.
  route = 'support';
  priority = 'normal';
  reason = `source=${source}`;
  tags = [source];
} else {
  const lowered = comment.toLowerCase();
  const matched = keywords.find((word) => lowered.includes(word));
  if (matched) {
    route = 'priority';
    priority = 'high';
    reason = `keyword:${matched}`;
    tags = ['hot', matched];
  } else if (comment) {
    route = 'sales';
    priority = 'normal';
    reason = 'comment_present';
    tags = ['with_comment'];
  } else {
    route = 'general';
    priority = 'normal';
    reason = 'default';
    tags = [];
  }
}

return [{
  json: {
    lead_id: lead.id || null,
    full_name: lead.full_name || '',
    phone: lead.phone || '',
    route,
    priority,
    reason,
    tags,
    created_at: lead.created_at || null,
  },
}];

